function Canvas({ draw, className }: { draw: (context: CanvasRenderingContext2D, width: number, height: number) => void; className?: string }) {
  const ref = useRef<HTMLCanvasElement>(null);
  useEffect(() => {
    const canvas = ref.current; if (!canvas) return;
    const density = Math.min(2, devicePixelRatio || 1), width = Math.max(1, Math.floor(canvas.clientWidth * density)), height = Math.max(1, Math.floor(canvas.clientHeight * density));
    canvas.width = width; canvas.height = height; draw(canvas.getContext("2d")!, width, height);
  }, [draw]);
  return <canvas ref={ref} className={className} />;
}

function BandpassOverlay({ preprocessing, onChange }: { preprocessing: PreprocessingConfig; onChange?: (value: PreprocessingConfig) => void }) {
  const [supportLow, supportHigh] = bandpassSupport(preprocessing);
  const move = (edge: "low" | "high", event: React.PointerEvent<HTMLButtonElement>) => {
    if (!onChange || !event.currentTarget.hasPointerCapture(event.pointerId)) return;
    const bounds = event.currentTarget.parentElement?.getBoundingClientRect(); if (!bounds) return;
    const hz = positionHz((event.clientY - bounds.top) / bounds.height);
    if (edge === "low") onChange({ ...preprocessing, lowCutoff: Math.round(Math.max(FREQ_MIN, Math.min(preprocessing.highCutoff - 50, hz)) / 5) * 5 });
    else onChange({ ...preprocessing, highCutoff: Math.round(Math.max(preprocessing.lowCutoff + 50, Math.min(FREQ_MAX, hz)) / 50) * 50 });
  };
  return <div className="spectrum-overlay bandpass-overlay" aria-hidden={!onChange}>
    {FREQ_TICKS.map((hz) => <span className="frequency-tick" style={{ top: `${hzPosition(hz)}%` }} key={hz}><i>{formatHz(hz)} Hz</i></span>)}
    <span className="filter-stop high" style={{ height: `${hzPosition(supportHigh)}%` }} />
    <span className="filter-stop low" style={{ top: `${hzPosition(supportLow)}%` }} />
    <span className="filter-transition high" style={{ top: `${hzPosition(supportHigh)}%`, height: `${Math.max(0, hzPosition(preprocessing.highCutoff) - hzPosition(supportHigh))}%` }} />
    <span className="filter-transition low" style={{ top: `${hzPosition(preprocessing.lowCutoff)}%`, height: `${Math.max(0, hzPosition(supportLow) - hzPosition(preprocessing.lowCutoff))}%` }} />
    {(["low", "high"] as const).map((edge) => { const hz = edge === "low" ? preprocessing.lowCutoff : preprocessing.highCutoff; return <button type="button" key={edge} className={`filter-edge ${onChange ? "interactive" : ""}`} style={{ top: `${hzPosition(hz)}%` }} onPointerDown={(event) => { if (onChange) event.currentTarget.setPointerCapture(event.pointerId); }} onPointerMove={(event) => move(edge, event)} onPointerUp={(event) => { if (event.currentTarget.hasPointerCapture(event.pointerId)) event.currentTarget.releasePointerCapture(event.pointerId); }} tabIndex={onChange ? 0 : -1}><b>{edge === "low" ? "HIGH-PASS" : "LOW-PASS"} · {formatHz(hz)} Hz</b></button>; })}
    <span className="filter-label">{preprocessing.window} · {preprocessing.transitionOctaves.toFixed(2)} oct taper</span>
  </div>;
}

function PatchThumbnail({ patch, color = "#c9ff72", title }: { patch: number[][]; color?: string; title?: string }) {
  const draw = useCallback((context: CanvasRenderingContext2D, width: number, height: number) => {
    context.fillStyle = "#05060a"; context.fillRect(0, 0, width, height);
    const maximum = Math.max(1e-9, quantile(patch.flat(), 0.995));
    patch.forEach((column, x) => column.forEach((value, f) => {
      const visible = Math.min(1, value / maximum), alpha = Math.max(0.05, visible);
      context.fillStyle = `${color}${Math.round(alpha * 255).toString(16).padStart(2, "0")}`;
      context.fillRect((x / patch.length) * width, height - ((f + 1) / column.length) * height, Math.ceil(width / patch.length) + 1, Math.ceil(height / column.length) + 1);
    }));
  }, [patch, color]);
  return <Canvas className="patch-thumbnail" draw={draw} key={title} />;
}

function EventBoxes({ result, selected, onSelect }: { result: Analysis; selected: string[]; onSelect: (id: string) => void }) {
  const colors = Object.fromEntries(result.tracks.map((track) => [track.id, track.color]));
  return <div className="event-boxes">{result.events.map((event) => {
    const top = hzPosition(Math.min(FREQ_MAX, event.highHz)), bottom = hzPosition(Math.max(FREQ_MIN, event.lowHz));
    return <button key={event.id} type="button" aria-label={`Select event ${event.id} from track ${event.trackId}`} className={selected.includes(event.id) ? "selected" : ""} onClick={() => onSelect(event.id)} style={{ left: `${100 * event.startSeconds / result.duration}%`, width: `${Math.max(0.7, 100 * (event.endSeconds - event.startSeconds) / result.duration)}%`, top: `${top}%`, height: `${Math.max(2.5, bottom - top)}%`, color: colors[event.trackId] ?? "#c9ff72" }}><span>{event.trackId}</span></button>;
  })}</div>;
}

